corrected_code:
const express = require('express');
const { Client } = require('@elastic/elasticsearch');
const { checkUserToken } = require('../auth');

const router = express.Router();
const esClient = new Client({ node: process.env.ELASTICSEARCH_URL });

router.get('/api/projections/bank-accounts/:accountId/statement', checkUserToken, async (req, res) => {
  const result = await esClient.get({
    index: 'bank_account_statement_projections',
    id: req.params.accountId
  });

  if (!result.found) return res.status(404).json({ error: 'Projection not found' });

  if (result._source.ownerUserId !== req.user.id && !req.user.isBankAuditor) {
    return res.status(403).json({ error: 'Forbidden: access denied to account statement' });
  }

  res.json(result._source);
});
